<?php
// Phase 6 tests: tasks, templates, email (real local SMTP), workflows, follow-ups, job queue (real CLI worker), notifications, timeline, security.
declare(strict_types=1);
$base = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/') . '/api'; $root = dirname(__DIR__, 2); $results = []; $jars = []; $tok = [];
$cfgFile = getenv('LTI_CONFIG'); $cfg = require $cfgFile; $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES => false]);
$q = function ($sql) use ($pdo) { return $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); }; $one = function ($sql) use ($q) { $r = $q($sql); return $r ? array_values($r[0])[0] : null; };
$sink = '/tmp/lti-smtp-sink'; shell_exec("rm -rf $sink; pkill -f '[s]mtp_sink.py'"); shell_exec("(setsid nohup python3 $root/tests/smtp_sink.py 2525 $sink </dev/null >/tmp/sink.log 2>&1 &)"); sleep(2);
$sinkCount = function () use ($sink) { return count(glob("$sink/*.eml") ?: []); };
$variant = function (array $mail) use ($cfg) { $c = $cfg; $c['mail'] = array_merge($cfg['mail'], $mail); $f = tempnam(sys_get_temp_dir(), 'cfg') . '.php'; file_put_contents($f, '<?php return ' . var_export($c, true) . ';'); return $f; };
$worker = function (?string $cfgPath = null, string $extra = '--once') use ($root, $cfgFile) { return (string)shell_exec('LTI_CONFIG=' . escapeshellarg($cfgPath ?: $cfgFile) . ' php ' . escapeshellarg("$root/server/app/bin/worker.php") . " $extra 2>&1"); };
function rq(string $who, string $m, string $p, $b = null, array $h = []): array { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar'); $ch = curl_init($base . $p); $hd = array_merge(['Accept: application/json'], $h); if (!empty($tok[$who]) && $m !== 'GET') $hd[] = 'X-CSRF-Token: ' . $tok[$who];
  if ($b !== null) { $hd[] = 'Content-Type: application/json'; curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($b)); } curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $m, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => $hd, CURLOPT_COOKIEJAR => $jars[$who], CURLOPT_COOKIEFILE => $jars[$who]]);
  $r = curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); return [$c, json_decode((string)$r, true) ?? [], (string)$r]; }
function login(string $who, string $e): void { global $tok; [$c, $d] = rq($who, 'POST', '/auth/login', ['email' => $e, 'password' => 'Dev-Password-2026']); if ($c !== 200) throw new Exception("login $e $c"); $tok[$who] = $d['csrf']; }
function t(string $n, callable $f): void { global $results; try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
foreach (['own' => 'owner@lti.test', 'adm' => 'admin@lti.test', 'adv' => 'advisor@lti.test', 'adv2' => 'advisor2@lti.test', 'fin' => 'finance@lti.test', 'sal' => 'sales@lti.test', 'trv' => 'traveler@lti.test'] as $k => $e) login($k, $e);
$tz = new DateTimeZone('America/New_York'); $today = (new DateTime('now', $tz))->format('Y-m-d'); $D = function ($n) use ($today) { return (new DateTime($today))->modify(($n >= 0 ? '+' : '') . $n . ' days')->format('Y-m-d'); };
$amalfi = (int)$one("SELECT id FROM trips WHERE name='Amalfi Coast Anniversary'"); $shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $adv = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'"); $adv2 = (int)$one("SELECT id FROM users WHERE email='advisor2@lti.test'"); $S = [];
// ---------- tasks ----------
t('TC01 Create task; MySQL record', function () use (&$S, $amalfi, $shah, $D, $one) { [$c, $d] = rq('adv', 'POST', '/tasks', ['title' => 'Confirm Capri boat time', 'description' => 'Call the skipper', 'priority' => 'high', 'dueDate' => $D(3), 'tripId' => $amalfi, 'contactId' => $shah]);
  ok($c === 201, "$c " . json_encode($d)); $S['t'] = $d['task']['id']; $r = $one("SELECT CONCAT_WS('|',status,priority,trip_id,contact_id,due_date) FROM tasks WHERE id={$S['t']}"); ok($r === "todo|high|$amalfi|$shah|" . $D(3), $r); return $r; });
t('TC02 Assign task to a staff member; history and notification recorded', function () use (&$S, $adv2, $one) { [, $g] = rq('adv', 'GET', "/tasks/{$S['t']}"); [$c] = rq('adv', 'PUT', "/tasks/{$S['t']}", ['assignedTo' => $adv2, 'version' => $g['task']['version']]);
  ok($c === 200 && (int)$one("SELECT assigned_to FROM tasks WHERE id={$S['t']}") === $adv2 && (int)$one("SELECT COUNT(*) FROM task_history WHERE task_id={$S['t']} AND field='assigned_to' AND new_value='$adv2'") === 1 && (int)$one("SELECT COUNT(*) FROM notifications WHERE user_id=$adv2 AND category='task_assignment' AND ref_id={$S['t']}") === 1, "$c"); return 'reassigned to advisor2; history + notification'; });
t('TC03 Edit task; persists; stale version 409', function () use (&$S, $D, $one) { [, $g] = rq('adv', 'GET', "/tasks/{$S['t']}"); [$c] = rq('adv', 'PUT', "/tasks/{$S['t']}", ['title' => 'Confirm Capri boat departure time', 'priority' => 'urgent', 'dueDate' => $D(2), 'status' => 'in_progress', 'version' => $g['task']['version']]);
  [$c2] = rq('adv', 'PUT', "/tasks/{$S['t']}", ['title' => 'x', 'version' => $g['task']['version']]); ok($c === 200 && $c2 === 409 && $one("SELECT CONCAT_WS('|',title,priority,status,due_date) FROM tasks WHERE id={$S['t']}") === 'Confirm Capri boat departure time|urgent|in_progress|' . $D(2), "$c $c2"); return 'saved'; });
t('TC04 Complete and reopen task', function () use (&$S, $one) { [$c, $d] = rq('adv2', 'POST', "/tasks/{$S['t']}/complete"); $ev = (int)$one("SELECT COUNT(*) FROM domain_events WHERE event_type='task.completed' AND entity_id={$S['t']}"); [$c2, $d2] = rq('adv2', 'POST', "/tasks/{$S['t']}/reopen"); [$c3] = rq('adv2', 'POST', "/tasks/{$S['t']}/reopen");
  ok($c === 200 && $d['task']['status'] === 'completed' && $ev === 1 && $c2 === 200 && $d2['task']['status'] === 'todo' && $c3 === 409, "$c $c2 $c3 ev=$ev"); return 'completed (event recorded), reopened, second reopen 409'; });
t('TC05 Overdue and upcoming filters use the agency time zone', function () use (&$S, $D) { [, $o] = rq('adv', 'POST', '/tasks', ['title' => 'Overdue passport check', 'dueDate' => $D(-2)]); [, $f] = rq('adv', 'POST', '/tasks', ['title' => 'Future visa check', 'dueDate' => $D(5)]);
  [, $l] = rq('adv', 'GET', '/tasks?overdue=1'); [, $up] = rq('adv', 'GET', '/tasks?upcomingDays=7'); $ids = array_column($l['items'], 'id'); $uids = array_column($up['items'], 'id');
  ok(in_array($o['task']['id'], $ids, true) && !in_array($f['task']['id'], $ids, true) && in_array($f['task']['id'], $uids, true) && $o['task']['overdue'] === true, json_encode([$ids, $uids])); return 'overdue and upcoming lists correct'; });
t('TC06 Unauthorized task access refused; tasks never reveal hidden CRM records', function () use (&$S, $shah, $adv2) { [, $mine] = rq('adv', 'POST', '/tasks', ['title' => 'Private advisor task']); [$c1] = rq('adv2', 'GET', '/tasks/' . $mine['task']['id']);
  [, $x] = rq('adv', 'POST', '/tasks', ['title' => 'Delegated', 'contactId' => $shah, 'assignedTo' => $adv2]); [, $g] = rq('adv2', 'GET', '/tasks/' . $x['task']['id']); [$c3] = rq('adv2', 'POST', '/tasks', ['title' => 'x', 'contactId' => $shah]); [$c4] = rq('trv', 'GET', '/tasks');
  ok($c1 === 404 && $g['task']['contact']['label'] === 'Restricted record' && $g['task']['contact']['id'] === null && $c3 === 404 && $c4 === 403, json_encode([$c1, $g['task']['contact'] ?? null, $c3, $c4])); return 'other advisor 404; linked contact shown as Restricted record; linking hidden contact 404; traveler 403'; });
// ---------- templates ----------
t('TC07 Create email template', function () use (&$S, $one) { [$c, $d] = rq('own', 'POST', '/email-templates', ['name' => 'Trip confirmation', 'category' => 'Booking', 'subject' => 'Your {{trip.name}} is confirmed', 'body' => "Hi {{contact.first_name}},\n\nGreat news: {{trip.name}} departs {{trip.departure_date}}.\n\nWarm regards,\n{{advisor.name}}\n{{agency.name}}"]);
  ok($c === 201, "$c " . json_encode($d)); $S['tpl'] = $d['template']['id']; ok($one("SELECT status FROM email_templates WHERE id={$S['tpl']}") === 'active', 'db'); return 'template ' . $S['tpl'] . ' with ' . count($d['template']['variables']) . ' variables'; });
t('TC08 Personalised variables render from linked records', function () use (&$S, $amalfi) { [$c, $d] = rq('adv', 'POST', "/email-templates/{$S['tpl']}/preview", ['tripId' => $amalfi]);
  ok($c === 200 && $d['subject'] === 'Your Amalfi Coast Anniversary is confirmed' && strpos($d['body'], 'Hi Daniel,') === 0 && strpos($d['body'], 'December 3, 2026') !== false && strpos($d['body'], 'Jordan Ellis') !== false && !$d['missing'], json_encode($d)); return $d['subject']; });
t('TC09 Invalid or unsafe variables rejected; advisors cannot manage templates', function () { [$c1, $e1] = rq('own', 'POST', '/email-templates', ['name' => 'Bad', 'subject' => 'Hi', 'body' => 'SSN {{contact.ssn}}']); [$c2] = rq('own', 'POST', '/email-templates', ['name' => 'Bad', 'subject' => 'Hi', 'body' => "{{ system('id') }}"]);
  [$c3] = rq('own', 'POST', '/email-templates', ['name' => 'Bad', 'subject' => "Hi\r\nBcc: x@y.z", 'body' => 'x']); [$c4] = rq('own', 'POST', '/email-templates', ['name' => 'Bad', 'subject' => 'Hi', 'body' => '<script>alert(1)</script>']); [$c5] = rq('adv', 'POST', '/email-templates', ['name' => 'x', 'subject' => 'x', 'body' => 'x']);
  ok($c1 === 422 && strpos($e1['error'], '{{contact.ssn}}') !== false && $c2 === 422 && $c3 === 422 && $c4 === 422 && $c5 === 403, "$c1 $c2 $c3 $c4 $c5"); return 'unknown variable, expression, header injection and script refused (422); advisor 403'; });
// ---------- email ----------
t('TC10 Save email draft from a template linked to contact and trip', function () use (&$S, $amalfi, $shah, $one) { [$c, $d] = rq('adv', 'POST', '/emails', ['templateId' => $S['tpl'], 'contactId' => $shah, 'tripId' => $amalfi]);
  ok($c === 201 && $d['email']['status'] === 'draft' && $d['email']['to'] === 'shah@example.com' && $one("SELECT status FROM emails WHERE id={$d['email']['id']}") === 'draft', "$c " . json_encode($d)); $S['em'] = $d['email']['id']; return 'draft ' . $S['em'] . ' to shah@example.com'; });
t('TC11–TC12 Queue email; real SMTP acceptance and failure recorded accurately', function () use (&$S, $worker, $variant, $sinkCount, $amalfi, $shah, $one) {
  [$c, $d] = rq('adv', 'POST', "/emails/{$S['em']}/queue"); ok($c === 200 && $d['email']['status'] === 'queued' && $d['email']['subject'] === 'Your Amalfi Coast Anniversary is confirmed' && (int)$one("SELECT COUNT(*) FROM scheduled_jobs WHERE dedupe_key='email:{$S['em']}' AND status='pending'") === 1, "queue $c");
  $before = $sinkCount(); $out = $worker(); $st = $one("SELECT CONCAT(status,'|',attempts) FROM emails WHERE id={$S['em']}"); $att = $one("SELECT result FROM email_send_attempts WHERE email_id={$S['em']}");
  $eml = implode('', array_map('file_get_contents', glob('/tmp/lti-smtp-sink/*.eml')));
  ok($st === 'accepted|1' && $att === 'accepted' && $sinkCount() === $before + 1 && strpos($eml, 'Hi Daniel,') !== false, "st=$st att=$att sink=" . $sinkCount() . ' ' . substr($out, 0, 200));
  [, $f] = rq('adv', 'POST', '/emails', ['contactId' => $shah, 'tripId' => $amalfi, 'subject' => 'Closed port test', 'body' => 'Hello {{contact.first_name}}']); rq('adv', 'POST', '/emails/' . $f['email']['id'] . '/queue');
  $bad = $variant(['port' => 2599]); for ($i = 0; $i < 3; $i++) { $worker($bad); $pdo = $GLOBALS['pdo']; $pdo->exec("UPDATE scheduled_jobs SET run_at=UTC_TIMESTAMP() WHERE dedupe_key='email:" . $f['email']['id'] . "' AND status='pending'"); }
  $fst = $one("SELECT CONCAT(status,'|',attempts) FROM emails WHERE id=" . $f['email']['id']); $fres = array_column($GLOBALS['q']("SELECT result FROM email_send_attempts WHERE email_id=" . $f['email']['id'] . " ORDER BY attempt_no"), 'result');
  [, $n] = rq('adv', 'POST', '/emails', ['contactId' => $shah, 'subject' => 'No transport', 'body' => 'x']); rq('adv', 'POST', '/emails/' . $n['email']['id'] . '/queue'); $worker($variant(['transport' => 'none'])); $nst = $one("SELECT CONCAT(status,'|',error) FROM emails WHERE id=" . $n['email']['id']);
  ok($fst === 'failed|3' && $fres === ['failed', 'failed', 'failed'] && strpos($nst, 'failed|Email transport is not configured') === 0, "$fst " . json_encode($fres) . " $nst");
  return 'accepted by local SMTP (message received, rendered); closed port: 3 failed attempts then Failed; no transport: Failed with explanation'; });
t('TC13 Duplicate sends prevented: crash mid-send becomes Unknown (never resent); parallel workers send once', function () use (&$S, $worker, $sinkCount, $shah, $one, $pdo, $root, $cfgFile) {
  [, $a] = rq('adv', 'POST', '/emails', ['contactId' => $shah, 'subject' => 'Crash test', 'body' => 'x']); rq('adv', 'POST', '/emails/' . $a['email']['id'] . '/queue'); $id = $a['email']['id'];
  $pdo->exec("UPDATE emails SET status='sending', attempts=1 WHERE id=$id"); $pdo->exec("UPDATE scheduled_jobs SET status='running', attempts=1, locked_by='crashed-worker', locked_until=UTC_TIMESTAMP() - INTERVAL 5 MINUTE, started_at=UTC_TIMESTAMP() - INTERVAL 10 MINUTE WHERE dedupe_key='email:$id'");
  $before = $sinkCount(); $worker(); $st = $one("SELECT status FROM emails WHERE id=$id"); $job = $one("SELECT CONCAT(status,'|',needs_review) FROM scheduled_jobs WHERE dedupe_key='email:$id'"); $worker();
  [$rc] = rq('adm', 'POST', '/jobs/' . $one("SELECT id FROM scheduled_jobs WHERE dedupe_key='email:$id'") . '/retry');
  ok($st === 'unknown' && $job === 'failed|1' && $sinkCount() === $before && $rc === 409, "st=$st job=$job sink " . $sinkCount() . " retry $rc");
  [, $b] = rq('adv', 'POST', '/emails', ['contactId' => $shah, 'subject' => 'Parallel test', 'body' => 'y']); rq('adv', 'POST', '/emails/' . $b['email']['id'] . '/queue'); $b0 = $sinkCount();
  $cmd = 'LTI_CONFIG=' . escapeshellarg($cfgFile) . ' php ' . escapeshellarg("$root/server/app/bin/worker.php") . ' --once >/dev/null 2>&1'; shell_exec("($cmd & $cmd & $cmd & wait)");
  ok($sinkCount() === $b0 + 1 && (int)$one('SELECT COUNT(*) FROM email_send_attempts WHERE email_id=' . $b['email']['id']) === 1, 'parallel sent ' . ($sinkCount() - $b0));
  [$r1] = rq('adv', 'POST', "/emails/$id/resolve", ['outcome' => 'accepted', 'note' => 'Client confirmed receipt by phone']); ok($r1 === 200 && $one("SELECT status FROM emails WHERE id=$id") === 'accepted', 'resolve'); return 'abandoned send -> Unknown, flagged, not resent, retry refused; 3 parallel workers -> exactly 1 SMTP message; manual resolution recorded'; });
// ---------- workflows ----------
t('TC14 Create workflow definition (validated on the server)', function () use (&$S, $one) { [$c, $d] = rq('own', 'POST', '/workflows', ['name' => 'Booked trip welcome', 'triggerType' => 'trip.status_changed', 'conditions' => [['field' => 'event.to', 'op' => 'eq', 'value' => 'Booked']],
  'actions' => [['type' => 'create_task', 'params' => ['title' => 'Send final documents for {{trip.name}}', 'priority' => 'high', 'dueInDays' => 3, 'assignTo' => 'entity_owner']], ['type' => 'notify', 'params' => ['to' => 'entity_owner', 'message' => '{{trip.name}} is booked', 'category' => 'new_booking']],
    ['type' => 'queue_email', 'params' => ['templateId' => $S['tpl']]], ['type' => 'schedule_followup', 'params' => ['inDays' => 2, 'atTime' => '09:00', 'action' => 'create_task', 'text' => 'Check {{contact.first_name}} received documents', 'assignTo' => 'entity_owner']], ['type' => 'timeline', 'params' => ['text' => 'Welcome sequence started']]]]);
  ok($c === 201 && $d['workflow']['status'] === 'draft', "$c " . json_encode($d)); $S['wf'] = $d['workflow']['id']; ok(strpos($one("SELECT actions_json FROM workflows WHERE id={$S['wf']}"), 'create_task') !== false, 'db'); return 'workflow ' . $S['wf'] . ' (draft) with 5 actions'; });
t('TC30 Unauthorized users cannot edit workflows; unsafe definitions refused', function () use (&$S) { $r = [];
  [$r['advisor create']] = rq('adv', 'POST', '/workflows', ['name' => 'x', 'triggerType' => 'trip.created', 'actions' => [['type' => 'timeline', 'params' => ['text' => 'x']]]]); [$r['finance enable']] = rq('fin', 'POST', "/workflows/{$S['wf']}/enable"); [$r['advisor edit']] = rq('adv', 'PUT', "/workflows/{$S['wf']}", ['name' => 'x']);
  [$r['sql action']] = rq('own', 'POST', '/workflows', ['name' => 'x', 'triggerType' => 'trip.created', 'actions' => [['type' => 'run_sql', 'params' => ['sql' => 'DELETE FROM invoices']]]]);
  [$r['financial status']] = rq('own', 'POST', '/workflows', ['name' => 'x', 'triggerType' => 'invoice.issued', 'actions' => [['type' => 'update_status', 'params' => ['target' => 'invoice.status', 'value' => 'paid']]]]);
  [$r['bad field']] = rq('own', 'POST', '/workflows', ['name' => 'x', 'triggerType' => 'trip.created', 'conditions' => [['field' => 'invoice.total', 'op' => 'gt', 'value' => '1']], 'actions' => [['type' => 'timeline', 'params' => ['text' => 'x']]]]);
  $exp = ['advisor create' => 403, 'finance enable' => 403, 'advisor edit' => 403, 'sql action' => 422, 'financial status' => 422, 'bad field' => 422]; ok($r == $exp, json_encode($r)); return json_encode($r); });
t('TC15 Enable and disable workflow', function () use (&$S, $one) { [$c1, $d1] = rq('own', 'POST', "/workflows/{$S['wf']}/disable"); [$c2, $d2] = rq('own', 'POST', "/workflows/{$S['wf']}/enable");
  ok($c1 === 200 && $d1['workflow']['status'] === 'disabled' && $c2 === 200 && $d2['workflow']['status'] === 'active' && $one("SELECT status FROM workflows WHERE id={$S['wf']}") === 'active', "$c1 $c2"); return 'disabled then active'; });
t('TC16–TC19 Real trip status change triggers the workflow: conditions, task, notification, email queued', function () use (&$S, $amalfi, $adv, $worker, $one) {
  [, $g] = rq('adv', 'GET', "/trips/$amalfi"); [$c] = rq('adv', 'PUT', "/trips/$amalfi", ['status' => 'Planning', 'version' => $g['trip']['version']]); $worker(); $skip = $one("SELECT CONCAT(status,'|',error) FROM workflow_executions WHERE workflow_id={$S['wf']} ORDER BY id DESC LIMIT 1");
  [, $g] = rq('adv', 'GET', "/trips/$amalfi"); [$c2] = rq('adv', 'PUT', "/trips/$amalfi", ['status' => 'Booked', 'version' => $g['trip']['version']]); $ev = (int)$one("SELECT COUNT(*) FROM domain_events WHERE event_type='trip.status_changed' AND entity_id=$amalfi");
  $worker(); $x = $q = $GLOBALS['q']("SELECT * FROM workflow_executions WHERE workflow_id={$S['wf']} ORDER BY id DESC LIMIT 1")[0]; $S['wx'] = (int)$x['id'];
  $task = $GLOBALS['q']("SELECT * FROM tasks WHERE dedupe_key='wx:{$x['id']}:a0'"); $notif = (int)$one("SELECT COUNT(*) FROM notifications WHERE user_id=$adv AND category='new_booking' AND dedupe_key LIKE 'wx:{$x['id']}:a1%'");
  $email = $one("SELECT status FROM emails WHERE workflow_execution_id={$x['id']}");
  ok($c === 200 && strpos($skip, 'skipped|Condition not met') === 0 && $c2 === 200 && $ev === 2 && $x['status'] === 'completed' && count($task) === 1 && $task[0]['title'] === 'Send final documents for Amalfi Coast Anniversary' && (int)$task[0]['assigned_to'] === $adv && $notif === 1 && in_array($email, ['queued', 'accepted'], true),
    json_encode([$skip, $x['status'], $x['error'], count($task), $notif, $email]));
  $worker(); return "Planning -> skipped (condition); Booked -> execution {$x['id']} completed: task for trip owner, notification, email " . $one("SELECT status FROM emails WHERE workflow_execution_id={$x['id']}"); });
t('TC20 Delayed follow-ups stored with UTC time from the configured time zone', function () use (&$S, $amalfi, $one, $D) { $f = $GLOBALS['q']("SELECT * FROM scheduled_followups WHERE workflow_execution_id={$S['wx']}")[0];
  $expUtc = (new DateTime($D(2) . ' 09:00', new DateTimeZone('America/New_York')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'); $job = $one("SELECT CONCAT(status,'|',run_at) FROM scheduled_jobs WHERE id={$f['job_id']}");
  [$c, $m] = rq('adv', 'POST', '/followups', ['entityType' => 'trip', 'entityId' => $amalfi, 'scheduledAt' => $D(1) . 'T08:30', 'timezone' => 'Asia/Manila', 'action' => 'notify', 'text' => 'Call client re: ferry']);
  $mUtc = (new DateTime($D(1) . ' 08:30', new DateTimeZone('Asia/Manila')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');
  ok($f['scheduled_at'] === $expUtc && $f['timezone'] === 'America/New_York' && $job === "pending|$expUtc" && $c === 201 && $m['followup']['scheduledAtUtc'] === $mUtc && $m['followup']['scheduledAtLocal'] === $D(1) . ' 08:30', json_encode([$f['scheduled_at'], $expUtc, $job, $m]));
  return "workflow follow-up $expUtc UTC (09:00 New York); manual follow-up 08:30 Manila = $mUtc UTC; jobs pending"; });
t('TC21 Pending jobs persist across a server restart', function () use ($one, $root, $cfgFile) { $n = (int)$one("SELECT COUNT(*) FROM scheduled_jobs WHERE status='pending'");
  shell_exec('pkill -f "[p]hp -S 127.0.0.1:8000"'); sleep(1); shell_exec('(LTI_CONFIG=' . escapeshellarg($cfgFile) . " PHP_CLI_SERVER_WORKERS=4 setsid nohup php -S 127.0.0.1:8000 -t $root/server/public $root/server/dev-router.php </dev/null >>/tmp/php-server.log 2>&1 &)"); sleep(2);
  login('adm', 'admin@lti.test'); [$c, $s] = rq('adm', 'GET', '/jobs/status'); $n2 = (int)$one("SELECT COUNT(*) FROM scheduled_jobs WHERE status='pending'");
  ok($n > 0 && $n2 === $n && $c === 200 && $s['counts']['pending'] === $n, "$n $n2 $c"); return "$n pending jobs before and after restart; visible in /jobs/status"; });
t('TC22 Concurrency-safe claiming: 3 parallel workers run each of 20 jobs exactly once', function () use ($pdo, $one, $root, $cfgFile, $amalfi, $adv) {
  for ($i = 0; $i < 20; $i++) { $pdo->exec("INSERT INTO scheduled_followups (entity_type, entity_id, assigned_to, scheduled_at, timezone, action, payload_json, status, created_by, created_at) VALUES ('trip',$amalfi,$adv,UTC_TIMESTAMP(),'UTC','create_task','{\"text\":\"Concurrency $i\"}','pending',$adv,UTC_TIMESTAMP())"); $fid = $pdo->lastInsertId();
    $pdo->exec("INSERT INTO scheduled_jobs (job_type, payload_json, run_at, status, attempts, max_attempts, dedupe_key, created_at) VALUES ('followup.run','{\"followupId\":$fid}',UTC_TIMESTAMP(),'pending',0,3,'cc:$fid',UTC_TIMESTAMP())"); }
  $cmd = 'LTI_CONFIG=' . escapeshellarg($cfgFile) . ' php ' . escapeshellarg("$root/server/app/bin/worker.php") . ' --once >/dev/null 2>&1'; shell_exec("($cmd & $cmd & $cmd & wait)");
  $tasks = (int)$one("SELECT COUNT(*) FROM tasks WHERE title LIKE 'Concurrency %'"); $dupLogs = (int)$one("SELECT COUNT(*) FROM (SELECT job_id FROM job_execution_logs l JOIN scheduled_jobs j ON j.id=l.job_id WHERE j.dedupe_key LIKE 'cc:%' AND l.result='completed' GROUP BY job_id HAVING COUNT(*)>1) x");
  $workers = (int)$one("SELECT COUNT(DISTINCT worker) FROM job_execution_logs l JOIN scheduled_jobs j ON j.id=l.job_id WHERE j.dedupe_key LIKE 'cc:%'");
  ok($tasks === 20 && $dupLogs === 0 && (int)$one("SELECT COUNT(*) FROM scheduled_jobs WHERE dedupe_key LIKE 'cc:%' AND status='completed'") === 20, "tasks=$tasks dup=$dupLogs workers=$workers"); return "20 tasks, no job run twice, $workers workers shared the load"; });
t('TC23–TC24 Recoverable failure retried with back-off then succeeds; repeated failure stops at the limit', function () use ($pdo, $one, $worker, $amalfi, $adv) {
  $pdo->exec("INSERT INTO scheduled_followups (entity_type, entity_id, assigned_to, scheduled_at, timezone, action, payload_json, status, created_by, created_at) VALUES ('trip',$amalfi,$adv,UTC_TIMESTAMP(),'UTC','queue_email','{\"text\":\"Retry me\"}','pending',$adv,UTC_TIMESTAMP())"); $f1 = $pdo->lastInsertId();
  $pdo->exec("INSERT INTO scheduled_jobs (job_type, payload_json, run_at, status, attempts, max_attempts, dedupe_key, created_at) VALUES ('followup.run','{\"followupId\":$f1}',UTC_TIMESTAMP(),'pending',0,3,'rt:$f1',UTC_TIMESTAMP())");
  $worker(); $a = $GLOBALS['q']("SELECT status, attempts, run_at > UTC_TIMESTAMP() later FROM scheduled_jobs WHERE dedupe_key='rt:$f1'")[0];
  $pdo->exec("UPDATE scheduled_followups SET action='create_task' WHERE id=$f1"); $pdo->exec("UPDATE scheduled_jobs SET run_at=UTC_TIMESTAMP() WHERE dedupe_key='rt:$f1'"); $worker(); $b = $one("SELECT CONCAT(status,'|',attempts) FROM scheduled_jobs WHERE dedupe_key='rt:$f1'");
  ok($a['status'] === 'pending' && (int)$a['attempts'] === 1 && (int)$a['later'] === 1 && $b === 'completed|2', json_encode([$a, $b]));
  $pdo->exec("INSERT INTO scheduled_followups (entity_type, entity_id, assigned_to, scheduled_at, timezone, action, payload_json, status, created_by, created_at) VALUES ('trip',$amalfi,$adv,UTC_TIMESTAMP(),'UTC','queue_email','{\"text\":\"Always fails\"}','pending',$adv,UTC_TIMESTAMP())"); $f2 = $pdo->lastInsertId();
  $pdo->exec("INSERT INTO scheduled_jobs (job_type, payload_json, run_at, status, attempts, max_attempts, dedupe_key, created_at) VALUES ('followup.run','{\"followupId\":$f2}',UTC_TIMESTAMP(),'pending',0,3,'rt:$f2',UTC_TIMESTAMP())");
  for ($i = 0; $i < 5; $i++) { $pdo->exec("UPDATE scheduled_jobs SET run_at=UTC_TIMESTAMP() WHERE dedupe_key='rt:$f2' AND status='pending'"); $worker(); }
  $c = $one("SELECT CONCAT(status,'|',attempts,'|',needs_review) FROM scheduled_jobs WHERE dedupe_key='rt:$f2'"); $logs = array_column($GLOBALS['q']("SELECT result FROM job_execution_logs l JOIN scheduled_jobs j ON j.id=l.job_id WHERE j.dedupe_key='rt:$f2' ORDER BY l.id"), 'result');
  ok($c === 'failed|3|1' && $logs === ['retry', 'retry', 'failed'], "$c " . json_encode($logs)); return 'retry scheduled later, then completed on attempt 2; permanent failure stopped after 3 attempts and flagged for review'; });
t('TC25 Abandoned worker job (expired lease) is recovered', function () use ($pdo, $one, $worker, $amalfi, $adv) {
  $pdo->exec("INSERT INTO scheduled_followups (entity_type, entity_id, assigned_to, scheduled_at, timezone, action, payload_json, status, created_by, created_at) VALUES ('trip',$amalfi,$adv,UTC_TIMESTAMP(),'UTC','create_task','{\"text\":\"Recovered work\"}','pending',$adv,UTC_TIMESTAMP())"); $f = $pdo->lastInsertId();
  $pdo->exec("INSERT INTO scheduled_jobs (job_type, payload_json, run_at, status, attempts, max_attempts, locked_by, locked_until, dedupe_key, created_at) VALUES ('followup.run','{\"followupId\":$f}',UTC_TIMESTAMP(),'running',1,3,'dead-worker',UTC_TIMESTAMP() - INTERVAL 1 MINUTE,'ab:$f',UTC_TIMESTAMP())");
  $worker(); $s = $one("SELECT status FROM scheduled_jobs WHERE dedupe_key='ab:$f'"); $log = $one("SELECT result FROM job_execution_logs l JOIN scheduled_jobs j ON j.id=l.job_id WHERE j.dedupe_key='ab:$f' ORDER BY l.id LIMIT 1");
  ok($s === 'completed' && $log === 'abandoned' && (int)$one("SELECT COUNT(*) FROM tasks WHERE title='Recovered work'") === 1, "$s $log"); return 'lease expired -> logged as abandoned -> re-run once -> completed'; });
t('TC26–TC27 Notifications persist; read, unread and dismiss', function () use ($adv) { login('adv-b', 'advisor@lti.test'); [, $l] = rq('adv-b', 'GET', '/notifications'); $id = $l['items'][0]['id']; $u0 = $l['unread'];
  [, $r] = rq('adv-b', 'POST', "/notifications/$id/read"); [, $u] = rq('adv-b', 'POST', "/notifications/$id/unread"); [, $d] = rq('adv-b', 'POST', "/notifications/$id/dismiss"); [$c] = rq('adv2', 'POST', "/notifications/$id/read");
  ok(count($l['items']) > 0 && $r['unread'] === $u0 - 1 && $u['unread'] === $u0 && !in_array($id, array_column($d['items'], 'id'), true) && $c === 404, json_encode([$u0, $r['unread'], $u['unread'], $c])); return "new session sees $u0 unread; read/unread/dismiss work; another user 404"; });
t('TC28 Activity timeline built from real events', function () use ($amalfi, $shah) { [, $t] = rq('adv', 'GET', "/activity?entityType=trip&entityId=$amalfi"); [, $c] = rq('adv', 'GET', "/activity?entityType=contact&entityId=$shah"); [$x] = rq('adv2', 'GET', "/activity?entityType=trip&entityId=$amalfi");
  $tt = array_column($t['items'], 'type'); $ct = array_column($c['items'], 'type'); foreach (['trip.status_changed', 'workflow.executed', 'workflow.note', 'task.created'] as $e) ok(in_array($e, $tt, true), "trip missing $e: " . json_encode($tt));
  foreach (['email.accepted', 'email.queued'] as $e) ok(in_array($e, $ct, true), "contact missing $e"); ok($x === 404, 'advisor2 saw timeline'); return 'trip: ' . implode(', ', array_slice(array_unique($tt), 0, 6)) . '; contact includes email events; hidden from advisor2'; });
t('TC29 Workflow execution history', function () use (&$S) { [, $e] = rq('own', 'GET', "/workflows/{$S['wf']}/executions"); $st = array_column($e['items'], 'status');
  ok(in_array('completed', $st, true) && in_array('skipped', $st, true) && count(array_filter($e['items'], function ($x) { return $x['status'] === 'completed' && count($x['result']) === 5; })) >= 1, json_encode($st)); return implode(', ', $st); });
t('Date trigger: departure approaching (agency time zone)', function () use ($amalfi, $worker, $one, $today) { $days = (int)(new DateTime($today))->diff(new DateTime('2026-12-03'))->format('%r%a');
  [$c, $d] = rq('own', 'POST', '/workflows', ['name' => 'Departure reminder', 'triggerType' => 'trip.departure_approaching', 'triggerConfig' => ['daysBefore' => $days], 'actions' => [['type' => 'notify', 'params' => ['to' => 'entity_owner', 'message' => 'Departure in ' . $days . ' days: {{trip.name}}', 'category' => 'upcoming_departure']]]]);
  rq('own', 'POST', '/workflows/' . $d['workflow']['id'] . '/enable'); $GLOBALS['pdo']->exec("DELETE FROM scheduled_jobs WHERE job_type='workflow.scan'"); $worker(); $worker();
  $n = (int)$one('SELECT COUNT(*) FROM workflow_executions WHERE workflow_id=' . $d['workflow']['id'] . " AND entity_id=$amalfi AND status='completed'"); ok($c === 201 && $n === 1, "$c n=$n days=$days"); return "execution for Amalfi ($days days before departure)"; });
t('TC32 Local scheduler: CLI worker and token-protected HTTP endpoint', function () use ($cfg, $one) { $n = (int)$one("SELECT COUNT(*) FROM scheduler_runs WHERE source='cli'");
  $h = curl_init($GLOBALS['base'] . '/cron/run'); curl_setopt_array($h, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => ['X-Cron-Token: ' . $cfg['cron_token']]]); $b = json_decode((string)curl_exec($h), true); $c = curl_getinfo($h, CURLINFO_HTTP_CODE);
  $h2 = curl_init($GLOBALS['base'] . '/cron/run'); curl_setopt_array($h2, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_HTTPHEADER => ['X-Cron-Token: wrong-token']]); curl_exec($h2); $c2 = curl_getinfo($h2, CURLINFO_HTTP_CODE);
  $h3 = curl_init($GLOBALS['base'] . '/cron/run'); curl_setopt_array($h3, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true]); curl_exec($h3); $c3 = curl_getinfo($h3, CURLINFO_HTTP_CODE);
  [, $s] = rq('adm', 'GET', '/jobs/status');
  ok($n >= 10 && $c === 200 && isset($b['jobs']) && $c2 === 403 && $c3 === 403 && $s['schedulerHealthy'] === true && (int)$one("SELECT COUNT(*) FROM scheduler_runs WHERE source='http'") === 1, "$n $c $c2 $c3"); return "$n CLI runs recorded; HTTP run with token 200; wrong/missing token 403; scheduler healthy"; });
t('TC37 Automations never alter financial records', function () use ($pdo, $one, $worker, $amalfi, $shah) {
  $snap = function () use ($one) { return $one("SELECT CONCAT_WS('|',(SELECT COALESCE(SUM(total),0) FROM invoices),(SELECT COALESCE(SUM(balance),0) FROM invoices),(SELECT COALESCE(SUM(amount_paid),0) FROM invoices),(SELECT COUNT(*) FROM payments),(SELECT COALESCE(SUM(amount),0) FROM payments),(SELECT COUNT(*) FROM commissions),(SELECT GROUP_CONCAT(status ORDER BY id) FROM invoices))"); };
  foreach (['invoice.issued', 'payment.recorded'] as $tr) { [, $w] = rq('own', 'POST', '/workflows', ['name' => "Finance watcher $tr", 'triggerType' => $tr, 'actions' => [['type' => 'create_task', 'params' => ['title' => "Review $tr", 'assignTo' => 'workflow_owner']], ['type' => 'notify', 'params' => ['to' => 'role:finance', 'message' => "$tr", 'category' => 'payment_update']], ['type' => 'timeline', 'params' => ['text' => $tr]]]]); rq('own', 'POST', '/workflows/' . $w['workflow']['id'] . '/enable'); }
  [, $i] = rq('adv', 'POST', '/invoices', ['contactId' => $shah, 'tripId' => $amalfi, 'currency' => 'USD', 'dueDate' => '2027-02-01', 'lines' => [['description' => 'Transfer', 'unitPrice' => '200.00']]]); rq('adv', 'POST', '/invoices/' . $i['invoice']['id'] . '/issue', []);
  rq('fin', 'POST', '/payments', ['invoiceId' => $i['invoice']['id'], 'amount' => '50.00', 'method' => 'cash']); $before = $snap(); $worker(); $worker(); $after = $snap();
  $ran = (int)$one("SELECT COUNT(*) FROM workflow_executions x JOIN workflows w ON w.id=x.workflow_id WHERE w.name LIKE 'Finance watcher%' AND x.status='completed'");
  ok($before === $after && $ran === 2 && (int)$one("SELECT COUNT(*) FROM tasks WHERE title IN ('Review invoice.issued','Review payment.recorded')") === 2, "before=$before after=$after ran=$ran"); return "2 finance-triggered workflows ran; invoice/payment/commission totals unchanged ($after)"; });
t('TC38 Credentials never appear in logs, errors or API responses', function () use ($worker, $variant, $shah, $one, $pdo) { $secret = 'Sup3r-Secret-SMTP-Pass!'; $cfgPath = $variant(['username' => 'lti-mailer', 'password' => $secret]);
  [, $e] = rq('adv', 'POST', '/emails', ['contactId' => $shah, 'subject' => 'Auth test', 'body' => 'z']); rq('adv', 'POST', '/emails/' . $e['email']['id'] . '/queue'); $worker($cfgPath);
  $hay = implode("\n", array_merge(array_column($GLOBALS['q']('SELECT error FROM emails'), 'error'), array_column($GLOBALS['q']('SELECT response FROM email_send_attempts'), 'response'), array_column($GLOBALS['q']('SELECT last_error FROM scheduled_jobs'), 'last_error'), array_column($GLOBALS['q']('SELECT message FROM job_execution_logs'), 'message')));
  [, , $api] = rq('adm', 'GET', '/jobs'); [, , $api2] = rq('adv', 'GET', '/emails'); [, , $api3] = rq('adm', 'GET', '/jobs/status'); $log = @file_get_contents('/tmp/php-server.log') ?: '';
  $att = $one('SELECT result FROM email_send_attempts WHERE email_id=' . $e['email']['id']);
  ok(strpos($hay . $api . $api2 . $api3 . $log, $secret) === false && strpos($api, 'payload') === false && $att !== null, 'secret leaked or attempt missing; attempt=' . $att); return "SMTP AUTH attempt recorded ($att); password absent from DB logs, API responses and server log; job payloads not exposed"; });
