echo "PHASE6 API SUMMARY $pass/" . count($results) . "\n"; file_put_contents(__DIR__ . '/api_phase6_results.json', json_encode($results, JSON_PRETTY_PRINT)); shell_exec("pkill -f \"[s]mtp_sink.py\""); exit($pass === count($results) ? 0 : 1);
